<?php
session_start(); require_once __DIR__.'/../autenticacao.php'; require_once __DIR__.'/conexaoDB.php'; require_once __DIR__.'/../cabecalho.php'; exigirLogin('gerente'); $farmaciaId=(int)$_SESSION['farmacia_id']; $id=(int)($_GET['id']??0);
$stmt=mysqli_prepare($conexao,'SELECT * FROM fornecedores WHERE id=? AND farmacia_id=?'); mysqli_stmt_bind_param($stmt,'ii',$id,$farmaciaId); mysqli_stmt_execute($stmt); $f=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); if(!$f){header('Location: fornecedores.php');exit;}
$stmt=mysqli_prepare($conexao,'SELECT e.*,p.nome produto,l.numero_lote,l.validade FROM entradas_mercadoria e INNER JOIN produtos p ON p.id=e.produto_id LEFT JOIN lotes l ON l.id=e.lote_id WHERE e.farmacia_id=? AND e.fornecedor_id=? ORDER BY e.id DESC'); mysqli_stmt_bind_param($stmt,'ii',$farmaciaId,$id); mysqli_stmt_execute($stmt); $entradas=mysqli_stmt_get_result($stmt);
?>
<!DOCTYPE html><html lang="pt-BR"><head><?php recursosCabeca('Histórico do fornecedor'); ?></head><body><?php cabecalho('FarmaCerta - Gerente','gerente','fornecedores'); ?><main class="container py-4"><section class="card card-brand rounded-4 p-4 mb-4"><h2 class="h3 fw-bold"><?php echo htmlspecialchars($f['nome']); ?></h2><p class="mb-0">Histórico de mercadorias recebidas deste fornecedor.</p></section><section class="card shadow-sm rounded-4 p-3"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Data</th><th>Produto</th><th>Lote</th><th>Validade</th><th>Qtd.</th><th>Custo unit.</th><th>Nota</th></tr></thead><tbody><?php while($e=mysqli_fetch_assoc($entradas)){ ?><tr><td><?php echo date('d/m/Y H:i',strtotime($e['criado_em'])); ?></td><td><?php echo htmlspecialchars($e['produto']); ?></td><td><?php echo htmlspecialchars($e['numero_lote']?:'-'); ?></td><td><?php echo $e['validade']?date('d/m/Y',strtotime($e['validade'])):'-'; ?></td><td><?php echo (int)$e['quantidade']; ?></td><td>R$ <?php echo number_format($e['custo_unitario'],2,',','.'); ?></td><td><?php echo htmlspecialchars($e['numero_nota']?:'-'); ?></td></tr><?php } ?></tbody></table></div></section></main><?php recursosRodape(); ?></body></html>